SELECT *
FROM tbl_authentication_data authentication

    authentication.final_status = '0000'


        AND authentication.trans_id = #{request.data.transId}



        AND authentication.create_date >= #{request.data.startCreateDate}::timestamp



        AND authentication.create_date <= #{request.data.endCreateDate}::timestamp



ORDER BY authentication.create_date DESC
LIMIT #{limit}
OFFSET #{startRow}
